#!/usr/bin/env python3
"""Generate `tests/common/sweep.rs`: a mechanical caller for every one of the 381
exported functions, used by `tests/sweep.rs` to hammer the FFI boundary with

  * NULL pointers in every pointer position,
  * 0 / negative / out-of-range values in every integer position (this is how a
    C enum with no valid variant crosses the boundary),

and to compare what the C and the Rust library do — including dying from the same
signal, since each call is made in a forked child.

Input is the *generated* `tests/common/api.rs`, so the argument lists are exactly
those of `png.h` / `pngpriv.h`.
"""
import re
import sys

API = 'tests/common/api.rs'
OUT = 'tests/common/sweep.rs'

src = open(API, encoding='utf-8').read()

FIELD = re.compile(r'^    pub (png_[A-Za-z0-9_]+): unsafe extern "C" fn\((.*)$',
                   re.M)


def mask_arrows(s):
    """`->` must not be seen as a closing angle bracket by the depth counter."""
    return s.replace('->', '@@')


def split_top(s):
    """Split a Rust argument list on top-level commas."""
    out, cur, depth = [], '', 0
    for ch, mch in zip(s, mask_arrows(s)):
        ch = mch if mch == '@' else ch
        if ch in '(<[':
            depth += 1
        elif ch in ')>]':
            depth -= 1
        if ch == ',' and depth == 0:
            out.append(cur.strip())
            cur = ''
        else:
            cur += (mch if mch != '@' else ch)
    if cur.strip():
        out.append(cur.strip())
    return out


def parse_field(line):
    """`pub name: unsafe extern "C" fn(ARGS) -> RET,` -> (name, [args], ret)."""
    line = line.rstrip()
    if line.endswith(','):
        line = line[:-1]
    m = re.match(r'^    pub (png_[A-Za-z0-9_]+): unsafe extern "C" fn\((.*)$',
                 line)
    if not m:
        return None
    name, rest = m.group(1), m.group(2)
    # find the closing paren of the argument list
    depth = 1
    i = 0
    masked = mask_arrows(rest)
    while i < len(rest):
        if masked[i] in '(<[':
            depth += 1
        elif masked[i] in ')>]':
            depth -= 1
            if depth == 0:
                break
        i += 1
    args = rest[:i]
    tail = rest[i + 1:].strip()
    ret = '()'
    if tail.startswith('->'):
        ret = tail[2:].strip()
    return name, split_top(args), ret


INTS = {'c_int': 'c_int', 'c_uint': 'c_uint', 'c_ulong': 'c_ulong',
        'u8': 'u8', 'u16': 'u16', 'u32': 'u32', 'i16': 'i16', 'i32': 'i32',
        'i64': 'i64', 'usize': 'usize'}
FLOATS = {'f32', 'f64'}


def zero_expr(t):
    if t.startswith('*mut'):
        return 'core::ptr::null_mut()'
    if t.startswith('*const'):
        return 'core::ptr::null()'
    if t.startswith('Option<') or t.endswith('_ptr'):
        return 'None'
    if t in INTS:
        return '0'
    if t in FLOATS:
        return '0.0'
    if t in ('png_xy', 'png_XYZ'):
        return 'Default::default()'
    raise SystemExit('zero_expr: unmapped %r' % t)


def val_expr(t, first_struct, first_info):
    """Value for the "hostile integer" sweep."""
    if t == '*mut PngStruct':
        return 'png'
    if t == '*mut PngInfo':
        return 'info'
    if t.startswith('*mut'):
        return 'core::ptr::null_mut()'
    if t.startswith('*const'):
        return 'core::ptr::null()'
    if t.startswith('Option<') or t.endswith('_ptr'):
        return 'None'
    if t in INTS:
        return '(v as %s)' % t
    if t in FLOATS:
        return '(v as %s)' % t
    if t in ('png_xy', 'png_XYZ'):
        return 'Default::default()'
    raise SystemExit('val_expr: unmapped %r' % t)


def fmt_ret(ret, expr):
    if ret == '()':
        return '{ %s; "void".to_string() }' % expr
    if ret == '*const c_char':
        return '{ let r = %s; fmt_cstr(r) }' % expr
    if ret.startswith('*'):
        return '{ let r = %s; fmt_ptr(r as *const u8) }' % expr
    if ret in FLOATS:
        return '{ let r = %s; format!("{:?}", r) }' % expr
    if ret in INTS:
        return '{ let r = %s; format!("{}", r) }' % expr
    if ret in ('png_xy', 'png_XYZ'):
        return '{ let r = %s; format!("{:?}", r) }' % expr
    raise SystemExit('fmt_ret: unmapped %r' % ret)


entries = []
for line in src.split('\n'):
    p = parse_field(line)
    if p:
        entries.append(p)

if not entries:
    raise SystemExit('no fields parsed from %s' % API)

out = []
w = out.append
w('// @generated by tools/gen_sweep.py from tests/common/api.rs -- do not edit.')
w('//')
w('// One arm per exported function.  `call_null` calls it with NULL/0 in every')
w('// position; `call_value` calls it with a live png_ptr/info_ptr and the same')
w('// hostile integer `v` in every scalar position (out-of-range enum values,')
w('// negative lengths, ...).  The result string is what the differential test')
w('// compares between the C and the Rust library.')
w('#![allow(non_snake_case, unused_variables, unused_unsafe, clippy::all)]')
w('')
w('use super::api::Api;')
w('use super::types::*;')
w('use core::ffi::{c_char, c_int, c_uint, c_ulong, c_void};')
w('')
w('pub const N: usize = %d;' % len(entries))
w('')
w('pub const NAMES: [&str; N] = [')
for name, _, _ in entries:
    w('    "%s",' % name)
w('];')
w('')
w('/// Does the function take at least one scalar argument (so that the hostile-')
w('/// integer sweep is meaningful for it)?')
w('pub const HAS_SCALAR: [bool; N] = [')
for name, args, ret in entries:
    has = any(a in INTS or a in FLOATS for a in args)
    w('    %s,' % ('true' if has else 'false'))
w('];')
w('')
w('/// Does the function take a `*mut PngStruct` as its first argument?')
w('pub const TAKES_PNG: [bool; N] = [')
for name, args, ret in entries:
    w('    %s,' % ('true' if args and args[0] == '*mut PngStruct' else 'false'))
w('];')
w('')
w('fn fmt_ptr(p: *const u8) -> String {')
w('    if p.is_null() { "null".to_string() } else { "ptr".to_string() }')
w('}')
w('')
w('unsafe fn fmt_cstr(p: *const c_char) -> String {')
w('    if p.is_null() {')
w('        "null".to_string()')
w('    } else {')
w('        format!("{:?}", core::ffi::CStr::from_ptr(p))')
w('    }')
w('}')
w('')
w('/// Call entry point `idx` with NULL / 0 in every argument position.')
w('pub unsafe fn call_null(api: &Api, idx: usize) -> String {')
w('    match idx {')
for i, (name, args, ret) in enumerate(entries):
    call = '(api.%s)(%s)' % (name, ', '.join(zero_expr(a) for a in args))
    w('        %d => %s,' % (i, fmt_ret(ret, call)))
w('        _ => unreachable!(),')
w('    }')
w('}')
w('')
w('/// Call entry point `idx` with a live `png`/`info` and the hostile value `v`')
w('/// in every scalar position.')
w('pub unsafe fn call_value(')
w('    api: &Api,')
w('    idx: usize,')
w('    png: *mut PngStruct,')
w('    info: *mut PngInfo,')
w('    v: i64,')
w(') -> String {')
w('    match idx {')
for i, (name, args, ret) in enumerate(entries):
    call = '(api.%s)(%s)' % (
        name, ', '.join(val_expr(a, True, True) for a in args))
    w('        %d => %s,' % (i, fmt_ret(ret, call)))
w('        _ => unreachable!(),')
w('    }')
w('}')
open(OUT, 'w').write('\n'.join(out) + '\n')
print('wrote %s with %d entry points' % (OUT, len(entries)))
